xpath.script:
function removeSpaces(inputElement) {
    // Get the input value and remove numbers
    let cleanedValue = inputElement.value.replace(/[0-9]/g, '');

    // Check if the cleaned value contains only alphabets and spaces
    if (/^[a-zA-Z\s]*$/.test(cleanedValue)) {
        // Input is valid - set the cleaned value as the input value
        inputElement.value = cleanedValue;
    } else {
        // Display an error message or take some other action to handle invalid input
        alert("Please enter only alphabets and spaces.");
        // Clear the input or take other actions as needed
        inputElement.value = '';
    }
}

